[DOC-BIN-01] Binary Search - Binary Search Pseudocode
function binarySearch(arr, target):
  low = 0
  high = arr.length - 1
  while low <= high:
    mid = low + Math.floor((high - low) / 2)
    if arr[mid] == target:
      return mid // Target found
    else if arr[mid] < target:
      low = mid + 1 // Target must reside in right half
    else:
      high = mid - 1 // Target must reside in left half
  return -1 // Target not present

[DOC-BST-01] Binary Search Tree (BST) - BST Search and Insertion Pseudocode
function search(node, target):
  if node is null or node.key == target:
    return node
  if target < node.key:
    return search(node.left, target)
  else:
    return search(node.right, target)

function insert(node, key):
  if node is null:
    return new Node(key)
  if key < node.key:
    node.left = insert(node.left, key)
  else if key > node.key:
    node.right = insert(node.right, key)
  return node

[DOC-BUB-01] Bubble Sort - Bubble Sort Pseudocode with Early Termination
procedure bubbleSort(arr, n):
  for i from 0 to n - 2:
    swapped = false
    for j from 0 to n - i - 2:
      if arr[j] > arr[j + 1]:
        swap(arr[j], arr[j + 1])
        swapped = true
    if not swapped:
      break // Early exit: array is already sorted
  return arr

[DOC-STK-01] Stack Data Structure - Stack Operations Pseudocode
class Stack(capacity):
  items = array of size capacity
  top = -1

  function push(x):
    if top == capacity - 1:
      raise StackOverflowError
    top = top + 1
    items[top] = x

  function pop():
    if top == -1:
      raise StackUnderflowError
    val = items[top]
    top = top - 1
    return val

  function peek():
    if top == -1:
      raise StackUnderflowError
    return items[top]
